Example Usage
Get started by installing the crate with cargo:
cargo add spark-connect
Next, initiate a session and execute queries against a Spark cluster:
// Connect to Spark
let session = SparkSessionBuilder::new("sc://localhost:15002").build().await?;

// Run a parameterized query
let batches = session
    .query("SELECT ? AS rule, ? AS text")
    .bind(42)
    .bind("world")
    .execute()
    .await?;
You can also use the sql() / collect() interface for lazy execution, similarly to idiomatic Spark:
use spark_connect::ToLiteral;

let lazy_plan = session.sql(
    "SELECT ? AS id, ? AS text",
    vec![42.to_literal(), "world".to_literal()]
).await?;

let batches = session.collect(lazy_plan);
